mapper.select:
SELECT receiver_area_id AS areaId, (SELECT COUNT(DISTINCT s.user_id) FROM trade_order s WHERE s.receiver_area_id = m.receiver_area_id
AND s.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
) AS orderCreateUserCount, (SELECT COUNT(DISTINCT s.user_id) FROM trade_order s WHERE s.receiver_area_id = m.receiver_area_id AND s.pay_status = TRUE AND s.deleted = 0
AND s.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
) AS orderPayUserCount, (SELECT SUM(s.pay_price) FROM trade_order s WHERE s.receiver_area_id = m.receiver_area_id AND s.pay_status = TRUE AND s.deleted = 0
AND s.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
) AS orderPayPrice FROM trade_order m WHERE deleted = 0
AND m.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
GROUP BY receiver_area_id

SELECT COUNT(DISTINCT (user_id))
FROM trade_order
WHERE deleted = 0
  AND create_time BETWEEN #{beginTime} AND #{endTime}

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT COUNT(DISTINCT (user_id))
FROM trade_order
WHERE pay_time BETWEEN #{beginTime} AND #{endTime}
  AND pay_status = TRUE
  AND deleted = 0

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT COUNT(1)
FROM trade_order
WHERE create_time BETWEEN #{beginTime} AND #{endTime}
  AND deleted = 0

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT COUNT(1)
FROM trade_order
WHERE pay_status = TRUE
  AND create_time BETWEEN #{beginTime} AND #{endTime}
  AND deleted = 0

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT SUM(pay_price)
FROM trade_order s
WHERE s.pay_status = TRUE
  AND deleted = 0
  AND create_time BETWEEN #{beginTime} AND #{endTime}

    AND s.tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT CAST(pay_time AS DATE) AS statDate, COUNT(1) AS order_pay_count, SUM(pay_price) AS order_pay_price FROM trade_order WHERE pay_status = TRUE AND create_time BETWEEN #{beginTime} AND #{endTime} AND deleted = 0
AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
GROUP BY CAST(pay_time AS DATE) ORDER BY statDate

SELECT CONCAT(EXTRACT(YEAR FROM pay_time), '-', LPAD(CONCAT(EXTRACT(MONTH FROM pay_time)), 2, '0')) AS statDate, COUNT(1) AS order_pay_count, SUM(pay_price) AS order_pay_price FROM trade_order WHERE pay_status = TRUE AND create_time BETWEEN #{beginTime} AND #{endTime} AND deleted = 0
AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
GROUP BY CONCAT(EXTRACT(YEAR FROM pay_time), '-', LPAD(CONCAT(EXTRACT(MONTH FROM pay_time)), 2, '0')) ORDER BY statDate

SELECT COUNT(1)
FROM trade_order
WHERE status = #{status}
  ANd delivery_type = #{deliveryType}
  AND deleted = 0

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}

SELECT COALESCE(SUM(pay_price), 0) AS order_pay_price,
       COUNT(1)                  AS order_pay_count
FROM trade_order
WHERE pay_status = #{payStatus}
  AND pay_time BETWEEN #{beginTime} AND #{endTime}
  AND deleted = 0

    AND tenant_id = ${@cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder@getTenantId()}
